create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text, role text default 'admin' check(role in ('admin','teacher','student','parent')), created_at timestamptz default now());
create table if not exists students(id bigint generated by default as identity primary key, name text not null, roll text unique not null, class_name text, section text, status text default 'Active', created_at timestamptz default now());
create table if not exists teachers(id bigint generated by default as identity primary key, name text not null, subject text, phone text, created_at timestamptz default now());
create table if not exists attendance(id bigint generated by default as identity primary key, student_id bigint references students(id) on delete cascade, date date not null, status text not null check(status in ('Present','Absent','Late')), created_at timestamptz default now());
create table if not exists results(id bigint generated by default as identity primary key, student_id bigint references students(id) on delete cascade, subject text not null, marks numeric not null, total numeric not null, created_at timestamptz default now());
create table if not exists fees(id bigint generated by default as identity primary key, student_id bigint references students(id) on delete cascade, month text not null, amount numeric not null, status text default 'Pending' check(status in ('Paid','Pending')), created_at timestamptz default now());
create table if not exists notices(id bigint generated by default as identity primary key, title text not null, body text not null, date date default current_date, created_at timestamptz default now());
alter table profiles enable row level security; alter table students enable row level security; alter table teachers enable row level security; alter table attendance enable row level security; alter table results enable row level security; alter table fees enable row level security; alter table notices enable row level security;
create policy "authenticated read" on students for select to authenticated using (true); create policy "authenticated write" on students for all to authenticated using (true) with check (true);
create policy "authenticated read teachers" on teachers for select to authenticated using (true); create policy "authenticated write teachers" on teachers for all to authenticated using (true) with check (true);
create policy "authenticated read attendance" on attendance for select to authenticated using (true); create policy "authenticated write attendance" on attendance for all to authenticated using (true) with check (true);
create policy "authenticated read results" on results for select to authenticated using (true); create policy "authenticated write results" on results for all to authenticated using (true) with check (true);
create policy "authenticated read fees" on fees for select to authenticated using (true); create policy "authenticated write fees" on fees for all to authenticated using (true) with check (true);
create policy "authenticated read notices" on notices for select to authenticated using (true); create policy "authenticated write notices" on notices for all to authenticated using (true) with check (true);
